// CSD_RATIONALE_BEGIN
// Dual-mode context-aware CSD for grade-school symbolic math.
//
// Failure analysis:
// - 32/49 examples (mode_A, mode_B): model writes MULTIPLE tiny spans separated
//   by operators outside spans: "<<total>> - <<2>> * <<n>> - <<m>>". Evaluator
//   extracts LAST span ("m") → wrong 1-variable answer. Avg span length 1.49 tokens.
// - 8/49 examples (mode_J, mode_K): model emits NO << at all. Caused by attempt 3
//   guidance saying "Do NOT use << >> during reasoning" — model avoided all delimiters.
// - 1/49: unterminated span (opened << near budget end with no close).
//
// Root cause of #1: Both attempt 2 (minSpanTokens=3) and attempt 3 (no minimum)
//   applied the SAME close policy to ALL spans. For intermediate reasoning spans,
//   immediate close is correct. For the FINAL answer span, we must NOT close on
//   IsCompletePrefix — we wait for EOS so the model signals the formula is done.
//
// Fix:
// (a) Permissive guidance: allow intermediate <<expr>> during reasoning (prevents
//     no-span failures), but demand the LAST span be ONE complete formula.
// (b) Context-aware span mode: when << is opened, check if "final answer is"
//     appears in rendered output. If YES → inFinalSpan=true. If NO → intermediate.
// (c) Intermediate spans: close immediately when IsCompletePrefix (fast close).
// (d) Final span: NEVER close on IsCompletePrefix. Penalize EOS for first
//     minFinalSpanToks steps to force formula growth. Accept EOS only when parser
//     deems the formula complete; then close before breaking.
// (e) Post-loop: if span still open and complete, close with remaining budget.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// parser_validity: `insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)`
//   Unconstrained branch: implication vacuous while !insideConstrainedOut. When
//   RenderedEndsWith(generated,"<<") fires, we set currentConstrainedOut := [] and
//   parser.IsValidPrefix([]) holds by method precondition.
//   Intermediate close branch (!inFinalSpan && IsCompletePrefix): CloseConstrainedSpan
//   sets insideConstrainedOut := false, making the implication vacuously true, and
//   clears currentConstrainedOut to [].
//   Constrained generation branch (else): AdaptiveConstrainedStepWithPenalties
//   returns EOS or a token t with parser.IsValidPrefix(currentConstrainedOut + [t]).
//   AppendConstrainedToken extends currentConstrainedOut by exactly t, preserving
//   IsValidPrefix. On EOS, if IsCompletePrefix holds, CloseConstrainedSpan sets
//   insideConstrainedOut := false (vacuously true); otherwise we break with
//   insideConstrainedOut still true but without appending an invalid token.
//   Post-loop close: guarded by IsCompletePrefix; CloseConstrainedSpan sets
//   insideConstrainedOut := false.
//
// progress: `|generated| <= |generatedPrefix| + steps`
//   Unconstrained branch: steps += 1; generated grows by at most 1 token (EOS not
//   appended; "<<" token is exactly 1 visible token). Bound preserved.
//   Intermediate close branch: steps += 1; CloseConstrainedSpan appends at most 1
//   delimiter (">>"); visible growth ≤ 1 = steps growth. Bound preserved.
//   Constrained generation branch: steps += 1 for AdaptiveConstrainedStepWithPenalties.
//   AppendConstrainedToken appends at most 1 expression token; visible growth ≤ 1.
//   On EOS path with close: second steps += 1 guarded by steps < maxSteps, so
//   steps stays ≤ maxSteps; CloseConstrainedSpan appends ≤ 1 token, so
//   |generated| ≤ |generatedPrefix| + steps_before_adaptive + 1 ≤ |generatedPrefix| + steps_after_close. Bound preserved.
//   Post-loop close: steps += 1 guarded by steps < maxSteps; CloseConstrainedSpan
//   appends ≤ 1 token; same accounting holds.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance := "Solve step by step in plain prose. You may use <<expr>> to highlight symbolic sub-results during reasoning. At the very end, write exactly: The final answer is <<FULL_FORMULA>> where FULL_FORMULA is a SINGLE complete arithmetic expression combining ALL required numeric variables with operators (+, -, *, /, //, %, (, ), int()). Do NOT split the final formula across multiple << >> spans — the entire expression must appear inside ONE pair of << >>.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var inFinalSpan: bool := false;
var minFinalSpanToks: nat := 5;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
      var genStr := CSDHelpers.PrefixToString(generated);
      var fc := CSDHelpers.CountSubstring(genStr, "final answer is");
      inFinalSpan := fc > 0;
    }
  } else if !inFinalSpan && parser.IsCompletePrefix(currentConstrainedOut) {
    // Intermediate span: close immediately when parser-complete
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
    inFinalSpan := false;
  } else {
    // Final span (or incomplete intermediate): generate constrained tokens.
    // Penalize EOS for the first minFinalSpanToks tokens in a final span
    // to push the model to grow the formula before signalling completion.
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var penaltyToks: seq<Token> := if inFinalSpan && |currentConstrainedOut| < minFinalSpanToks then [eosToken] else [];
    var next := helpers.AdaptiveConstrainedStepWithPenalties(
      lm, parser, constrainedPrompt, currentConstrainedOut,
      validTokenGroups, 4.0, penaltyToks, 6.0, 12, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      // EOS fired: close span if it is currently parser-complete
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Post-loop cleanup: if still inside an open span that is parser-complete, close it
if insideConstrainedOut && parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
  var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + 1;
}

cost := steps;

